const fs = require("fs");
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, BorderStyle, WidthType, ShadingType, VerticalAlign,
        LevelFormat, HeadingLevel } = require("docx");

const NAVY = "1F3864";
const GREYLINE = "BFBFBF";
const LIGHT = "EDF1F7";

const noBorders = {
  top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE },
  left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE },
};
const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: "D5DCE4" };
const cellBorders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };

function fieldCell(text) {
  return new TableCell({
    borders: cellBorders, width: { size: 2880, type: WidthType.DXA },
    shading: { fill: LIGHT, type: ShadingType.CLEAR },
    margins: { top: 120, bottom: 120, left: 160, right: 160 },
    verticalAlign: VerticalAlign.TOP,
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, color: NAVY, size: 22 })] })],
  });
}
function detailCell(children) {
  return new TableCell({
    borders: cellBorders, width: { size: 6480, type: WidthType.DXA },
    margins: { top: 120, bottom: 120, left: 160, right: 160 },
    verticalAlign: VerticalAlign.TOP,
    children,
  });
}
const p = (runs, opts = {}) => new Paragraph({ children: runs, spacing: { after: 60 }, ...opts });
const t = (text, o = {}) => new TextRun({ text, size: 22, ...o });
function bullet(text) {
  return new Paragraph({
    numbering: { reference: "reqs", level: 0 },
    spacing: { after: 40 },
    children: [new TextRun({ text, size: 22 })],
  });
}

const row = (field, detailChildren) =>
  new TableRow({ children: [fieldCell(field), detailCell(detailChildren)] });

const table = new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [2880, 6480],
  rows: [
    row("Ticket Size", [
      p([t("$10,000 to $15,000 one-time. DWY program at $10,000, DFY program at $15,000.")]),
      p([t("DFY clients add a $2,500 per month partnership after their 90-day program. Blended deal value is about $12,000.")]),
    ]),
    row("Current Monthly Revenue", [
      p([t("Approximately $20,000 per month at present.")]),
      p([t("A new lead engine is launching that the team is being built to scale, with revenue projected to grow steadily through 2026 and 2027.")]),
    ]),
    row("Closer Compensation", [
      p([t("$2,500 per month base or draw, plus 10 percent commission on the one-time program value.")]),
      p([t("That is $1,000 on a $10,000 DWY sale and $1,500 on a $15,000 DFY sale.")]),
      p([t("On-target earnings of roughly $12,000 to $16,000 per month, about $150,000 to $190,000 per year, once lead volume is at full ramp. Earnings are lower during the first 60 to 90 days while volume builds.")]),
    ]),
    row("Experience Requirements", [
      bullet("Two or more years of high-ticket, consultative closing by phone or video."),
      bullet("Proven track record closing offers of $10,000 or more, ideally in consulting, coaching, agency, or service-business sales."),
      bullet("Comfortable selling to business owners. Med spa, aesthetics, or wellness experience is a plus."),
      bullet("Strong CRM and pipeline discipline with consistent follow-up."),
      bullet("Runs a structured sales process and holds price without discounting."),
      bullet("Self-managed and reliable in a remote setting."),
    ]),
    row("Time Commitment", [
      p([t("Full-time. Roughly two to three booked sales calls per day at capacity, about 40 sales calls per month per closer, plus follow-up, pipeline management, and CRM updates.")]),
      p([t("Standard business hours with some flexibility for prospect time zones.")]),
    ]),
  ],
});

const doc = new Document({
  numbering: {
    config: [{ reference: "reqs", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022",
      alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 360, hanging: 220 } } } }] }],
  },
  styles: { default: { document: { run: { font: "Arial", size: 22 } } } },
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 },
      margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 } } },
    children: [
      new Paragraph({
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        spacing: { before: 0, after: 0 },
        children: [new TextRun({ text: "  THE LUXORA COLLECTIVE", bold: true, color: "FFFFFF", size: 26 })],
      }),
      new Paragraph({
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        spacing: { before: 0, after: 200 },
        children: [new TextRun({ text: "  Closer Role: Hiring Brief", color: "FFFFFF", size: 20, italics: true })],
      }),
      new Paragraph({
        spacing: { after: 240 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: NAVY, space: 1 } },
        children: [new TextRun({ text: "Prepared for our recruiting partner. Role: High-ticket Closer.", size: 22, color: "404040" })],
      }),
      table,
      new Paragraph({ spacing: { before: 320, after: 0 },
        border: { top: { style: BorderStyle.SINGLE, size: 6, color: NAVY, space: 6 } },
        children: [new TextRun({ text: "Bethany Anne", bold: true, size: 22, color: NAVY })] }),
      new Paragraph({ spacing: { after: 0 },
        children: [new TextRun({ text: "Co-Founder & CEO, The Luxora Collective", size: 20, color: "404040" })] }),
      new Paragraph({ spacing: { after: 0 },
        children: [new TextRun({ text: "theluxoracollective.co", size: 20, color: "404040" })] }),
    ],
  }],
});

Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync("/home/claude/Luxora_Closer_Hiring_Brief.docx", buf);
  console.log("written");
});

